import type { Inspection } from './inspection.js';

export function validate(r: Partial<Inspection>): string[] {
  const errors: string[] = [];
  if (!r.id) errors.push('id is required');
  if (!r.siteId) errors.push('siteId is required');
  if (r.status && !['draft', 'submitted'].includes(r.status)) errors.push('bad status');
  return errors;
}

