import { createHmac } from 'node:crypto';

export function issueToken(deviceId: string, secret: string, ttlSec = 86400) {
  const exp = Math.floor(Date.now() / 1000) + ttlSec;
  const sig = createHmac('sha256', secret).update(`${deviceId}.${exp}`).digest('hex');
  return `${deviceId}.${exp}.${sig}`;
}

