const seen = new Map<string, number>();

export function isDuplicate(clientOpId: string, ttlMs = 10 * 60_000): boolean {
  const now = Date.now();
  const at = seen.get(clientOpId);
  seen.set(clientOpId, now);
  return at !== undefined && now - at < ttlMs;
}

