export interface PhotoJob { photoId: string; attempts: number; nextAt: number }

export class PhotoQueue {
  private jobs: PhotoJob[] = [];
  add(photoId: string) { this.jobs.push({ photoId, attempts: 0, nextAt: 0 }); }
  due(now = Date.now()) { return this.jobs.filter(j => j.nextAt <= now); }
  fail(job: PhotoJob, delayMs: number) { job.attempts++; job.nextAt = Date.now() + delayMs; }
}

