export const CHUNK_SIZE = 512 * 1024;

export function chunks(size: number): Array<[number, number]> {
  const out: Array<[number, number]> = [];
  for (let start = 0; start < size; start += CHUNK_SIZE) out.push([start, Math.min(start + CHUNK_SIZE, size)]);
  return out;
}

