export function schedule(sync: () => Promise<void>, everyMs = 15 * 60_000) {
  let busy = false;
  return setInterval(async () => {
    if (busy) return;
    busy = true;
    try { await sync(); } finally { busy = false; }
  }, everyMs);
}

