export interface ExportFilter { siteId?: string; from?: string; to?: string }

export function whereClause(f: ExportFilter): string {
  const parts = ['1 = 1'];
  if (f.siteId) parts.push('site_id = @siteId');
  if (f.from) parts.push('submitted_at >= @from');
  if (f.to) parts.push('submitted_at < @to');
  return parts.join(' AND ');
}

